CREATE TABLE public.cash_hand_participant_manifests("id" uuid DEFAULT gen_random_uuid() NOT NULL,"table_id" uuid NOT NULL,"hand_number" bigint NOT NULL,"captured_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,"lease_instance_id" text NOT NULL,"lease_generation" uuid NOT NULL,"request" jsonb NOT NULL,"game_scope" jsonb NOT NULL,"participants" jsonb NOT NULL,"issues" jsonb NOT NULL,"funding_provenance_complete" boolean NOT NULL);
CREATE TABLE public.cash_participant_funding_receipts("id" uuid DEFAULT gen_random_uuid() NOT NULL,"recorded_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,"operation_kind" text NOT NULL,"operation_key" text,"user_id" uuid NOT NULL,"table_id" uuid NOT NULL,"seat_id" uuid NOT NULL,"occupancy_id" uuid NOT NULL,"seat_joined_at" timestamp with time zone NOT NULL,"source_ledger_id" uuid NOT NULL,"wallet_transaction_id" uuid,"account_type" text NOT NULL,"account_entity_id" uuid NOT NULL,"funding_club_id" uuid NOT NULL,"funding_union_id" uuid,"asset" text NOT NULL,"unit_scale" integer DEFAULT 2 NOT NULL,"amount" numeric NOT NULL,"balance_before" numeric NOT NULL,"balance_after" numeric NOT NULL,"pending_addon_id" uuid,"transaction_id" xid8 DEFAULT pg_current_xact_id());
CREATE TABLE public.union_pnl_inventory_events("event_id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,"source_name" text NOT NULL,"row_id" uuid NOT NULL,"observed_at" timestamp with time zone NOT NULL,"transaction_id" xid8 NOT NULL,"operation" text NOT NULL,"before_row" jsonb,"after_row" jsonb);
CREATE TABLE public.wallet_transactions("id" uuid DEFAULT gen_random_uuid() NOT NULL,"user_id" uuid NOT NULL,"wallet_type" text NOT NULL,"amount" numeric(15,2) NOT NULL,"type" text NOT NULL,"category" text NOT NULL,"description" text,"related_entity_id" uuid,"table_id" uuid,"hand_id" uuid,"created_at" timestamp with time zone DEFAULT now(),"balance_after" numeric,"terminal_closed_at" timestamp with time zone);
CREATE TABLE public.hand_atomic_commits(hand_id uuid PRIMARY KEY,table_id uuid,hand_number bigint,payload_hash text,stack_result jsonb,committed_at timestamptz,post_commit_completed_at timestamptz,post_commit_result jsonb);
CREATE TABLE smarter_private.hand_submissions(submission_id uuid PRIMARY KEY,request_hash text,table_id uuid,hand_number bigint,lease_generation uuid,request jsonb,retained_at timestamptz);